     1|/**
     2| * IVX Autonomous Dashboard — live W1–W12 job ledger (owner-only).
     3| *
     4| * Reads REAL production data from:
     5| *   GET https://api.ivxholding.com/api/ivx/autonomous/ledger
     6| *
     7| * No seed data: every job shown carries a stable job ID, status history with
     8| * timestamps, evidence, and blockers straight from the durable backend ledger.
     9| * Auto-refreshes via controlled polling (30s) + pull-to-refresh.
    10| */
    11|import React, { useState, useCallback, useEffect, useRef } from 'react';
    12|import {
    13|  View,
    14|  Text,
    15|  StyleSheet,
    16|  ScrollView,
    17|  TouchableOpacity,
    18|  ActivityIndicator,
    19|  RefreshControl,
    20|} from 'react-native';
    21|import { SafeAreaView } from 'react-native-safe-area-context';
    22|import { Stack, useRouter } from 'expo-router';
    23|import {
    24|  Activity,
    25|  AlertTriangle,
    26|  ArrowLeft,
    27|  CheckCircle2,
    28|  ChevronDown,
    29|  ChevronRight,
    30|  Clock,
    31|  Cpu,
    32|  ListChecks,
    33|  Lock,
    34|  RefreshCw,
    35|  ShieldCheck,
    36|} from 'lucide-react-native';
    37|import { getIVXAccessToken } from '@/lib/ivx-supabase-client';
    38|
    39|const API_BASE = (process.env.EXPO_PUBLIC_IVX_API_BASE_URL || 'https://api.ivxholding.com').replace(/\/+$/, '');
    40|const LEDGER_URL = `${API_BASE}/api/ivx/autonomous/ledger`;
    41|const POLL_INTERVAL_MS = 30_000;
    42|
    43|type LedgerWorker = { id: string; name: string; scope: string };
    44|
    45|type LedgerHistoryEntry = { at: string; from: string | null; to: string; note: string | null };
    46|
    47|type LedgerJob = {
    48|  jobId: string;
    49|  workerId: string;
    50|  title: string;
    51|  status: string;
    52|  priority: string;
    53|  evidence: string | null;
    54|  blocker: string | null;
    55|  createdAt: string;
    56|  updatedAt: string;
    57|  history: LedgerHistoryEntry[];
    58|};
    59|
    60|type LedgerApproval = {
    61|  approvalId: string;
    62|  workerId: string;
    63|  title: string;
    64|  risk: string;
    65|  rollback: string;
    66|  status: string;
    67|  createdAt: string;
    68|};
    69|
    70|type LedgerCounts = {
    71|  workers: number;
    72|  jobs: number;
    73|  verified: number;
    74|  running: number;
    75|  blocked: number;
    76|  ownerActionRequired: number;
    77|  queued: number;
    78|  pendingApprovals: number;
    79|};
    80|
    81|type LedgerResponse = {
    82|  ok: boolean;
    83|  error?: string;
    84|  marker?: string;
    85|  generatedAt?: string;
    86|  version?: number;
    87|  updatedAt?: string;
    88|  counts?: LedgerCounts;
    89|  workers?: LedgerWorker[];
    90|  jobs?: LedgerJob[];
    91|  approvals?: LedgerApproval[];
    92|};
    93|
    94|const STATUS_COLORS: Record<string, string> = {
    95|  VERIFIED: '#34D399',
    96|  DONE: '#34D399',
    97|  RUNNING: '#FBBF24',
    98|  QUEUED: '#94A3B8',
    99|  BLOCKED: '#F87171',
   100|  OWNER_ACTION_REQUIRED: '#F97316',
   101|};
   102|
   103|const STATUS_ORDER: string[] = ['RUNNING', 'BLOCKED', 'OWNER_ACTION_REQUIRED', 'QUEUED', 'VERIFIED', 'DONE'];
   104|
   105|function statusColor(status: string): string {
   106|  return STATUS_COLORS[status] ?? '#94A3B8';
   107|}
   108|
   109|function formatTime(iso: string | null | undefined): string {
   110|  if (!iso) return '—';
   111|  try {
   112|    const d = new Date(iso);
   113|    return `${d.toISOString().slice(0, 10)} ${d.toISOString().slice(11, 16)} UTC`;
   114|  } catch {
   115|    return iso;
   116|  }
   117|}
   118|
   119|export default function AutonomousDashboardScreen() {
   120|  const router = useRouter();
   121|  const [data, setData] = useState<LedgerResponse | null>(null);
   122|  const [isLoading, setIsLoading] = useState<boolean>(true);
   123|  const [isRefreshing, setIsRefreshing] = useState<boolean>(false);
   124|  const [errorMessage, setErrorMessage] = useState<string | null>(null);
   125|  const [isUnauthorized, setIsUnauthorized] = useState<boolean>(false);
   126|  const [expandedJobId, setExpandedJobId] = useState<string | null>(null);
   127|  const [lastFetchedAt, setLastFetchedAt] = useState<string | null>(null);
   128|  const pollRef = useRef<ReturnType<typeof setInterval> | null>(null);
   129|
   130|  const fetchLedger = useCallback(async (silent: boolean) => {
   131|    if (!silent) setIsLoading(true);
   132|    setErrorMessage(null);
   133|    try {
   134|      const token = await getIVXAccessToken();
   135|      if (!token) {
   136|        setIsUnauthorized(true);
   137|        setErrorMessage('Owner session required. Sign in as the owner to view the autonomous ledger.');
   138|        return;
   139|      }
   140|      const response = await fetch(LEDGER_URL, {
   141|        method: 'GET',
   142|        headers: { Authorization: `Bearer ${token}` },
   143|      });
   144|      if (response.status === 401 || response.status === 403) {
   145|        setIsUnauthorized(true);
   146|        setErrorMessage('Access denied: this dashboard is restricted to the IVX owner.');
   147|        return;
   148|      }
   149|      const json = (await response.json()) as LedgerResponse;
   150|      if (!json.ok) {
   151|        setErrorMessage(json.error ?? `Ledger request failed (HTTP ${response.status}).`);
   152|        return;
   153|      }
   154|      setIsUnauthorized(false);
   155|      setData(json);
   156|      setLastFetchedAt(new Date().toISOString());
   157|    } catch (err) {
   158|      const message = err instanceof Error ? err.message : 'Network error loading ledger.';
   159|      console.log('[AutonomousDashboard] fetch failed:', message);
   160|      setErrorMessage(message);
   161|    } finally {
   162|      setIsLoading(false);
   163|      setIsRefreshing(false);
   164|    }
   165|  }, []);
   166|
   167|  useEffect(() => {
   168|    fetchLedger(false);
   169|    pollRef.current = setInterval(() => fetchLedger(true), POLL_INTERVAL_MS);
   170|    return () => {
   171|      if (pollRef.current) clearInterval(pollRef.current);
   172|    };
   173|  }, [fetchLedger]);
   174|
   175|  const onRefresh = useCallback(() => {
   176|    setIsRefreshing(true);
   177|    fetchLedger(true);
   178|  }, [fetchLedger]);
   179|
   180|  const counts = data?.counts;
   181|  const jobs = data?.jobs ?? [];
   182|  const workers = data?.workers ?? [];
   183|  const approvals = (data?.approvals ?? []).filter((a) => a.status === 'PENDING');
   184|  const sortedJobs = [...jobs].sort((a, b) => {
   185|    const sa = STATUS_ORDER.indexOf(a.status);
   186|    const sb = STATUS_ORDER.indexOf(b.status);
   187|    if (sa !== sb) return sa - sb;
   188|    return a.jobId.localeCompare(b.jobId);
   189|  });
   190|  const completionPercent = counts && counts.jobs > 0 ? Math.round((counts.verified / counts.jobs) * 100) : 0;
   191|
   192|  return (
   193|    <SafeAreaView style={styles.safeArea} edges={['top', 'bottom']}>
   194|      <Stack.Screen options={{ headerShown: false }} />
   195|      <View style={styles.header}>
   196|        <TouchableOpacity onPress={() => router.back()} style={styles.backButton} testID="autonomous-dashboard-back">
   197|          <ArrowLeft size={22} color="#E2E8F0" />
   198|        </TouchableOpacity>
   199|        <View style={styles.headerTitleWrap}>
   200|          <Text style={styles.headerTitle}>Autonomous Dashboard</Text>
   201|          <Text style={styles.headerSubtitle}>
   202|            Live ledger · v{data?.version ?? '—'} · {formatTime(lastFetchedAt)}
   203|          </Text>
   204|        </View>
   205|        <TouchableOpacity onPress={onRefresh} style={styles.refreshButton} testID="autonomous-dashboard-refresh">
   206|          <RefreshCw size={18} color="#FBBF24" />
   207|        </TouchableOpacity>
   208|      </View>
   209|
   210|      {isLoading ? (
   211|        <View style={styles.centerFill}>
   212|          <ActivityIndicator size="large" color="#FBBF24" />
   213|          <Text style={styles.loadingText}>Loading live job ledger…</Text>
   214|        </View>
   215|      ) : isUnauthorized ? (
   216|        <View style={styles.centerFill}>
   217|          <Lock size={40} color="#F87171" />
   218|          <Text style={styles.errorTitle}>Owner access required</Text>
   219|          <Text style={styles.errorBody}>{errorMessage}</Text>
   220|        </View>
   221|      ) : errorMessage && !data ? (
   222|        <View style={styles.centerFill}>
   223|          <AlertTriangle size={40} color="#F87171" />
   224|          <Text style={styles.errorTitle}>Could not load ledger</Text>
   225|          <Text style={styles.errorBody}>{errorMessage}</Text>
   226|          <TouchableOpacity style={styles.retryButton} onPress={() => fetchLedger(false)}>
   227|            <Text style={styles.retryText}>Retry</Text>
   228|          </TouchableOpacity>
   229|        </View>
   230|      ) : (
   231|        <ScrollView
   232|          style={styles.scroll}
