   234|          refreshControl={<RefreshControl refreshing={isRefreshing} onRefresh={onRefresh} tintColor="#FBBF24" />}
   235|        >
   236|          {counts ? (
   237|            <View style={styles.card}>
   238|              <View style={styles.cardHeaderRow}>
   239|                <Activity size={16} color="#FBBF24" />
   240|                <Text style={styles.cardHeader}>Overview</Text>
   241|              </View>
   242|              <View style={styles.progressTrack}>
   243|                <View style={[styles.progressFill, { width: `${completionPercent}%` }]} />
   244|              </View>
   245|              <Text style={styles.progressLabel}>{completionPercent}% verified ({counts.verified}/{counts.jobs} jobs)</Text>
   246|              <View style={styles.statGrid}>
